{"path":"index.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width, initial-scale=1'>
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name='description' content='Intensive therapy offerings, short series, and gentle continuity support in {{CITY}}, {{STATE}}.'>
  <link rel='icon' href='data:,'>
  <style>html,body{height:100%}</style>
  <link rel='stylesheet' href='assets/css/styles.css'>
</head>
<body>
  <div class='site-root'>
    <header class='topbar'>
      <div class='wrap topbar-grid'>
        <a class='brand' href='index.html' aria-label='home'>
          <svg class='mark' viewBox='0 0 100 100' role='img' aria-hidden='true'><rect width='100' height='100' rx='16' fill='url(#p)'></rect><defs><pattern id='p' patternUnits='userSpaceOnUse' width='20' height='20'><rect width='20' height='20' fill='#111827'></rect><circle cx='10' cy='10' r='4' fill='#8b5cf6' fill-opacity='0.12'></circle></pattern></defs></svg>
          <div class='brand-text'>
            <div class='name'>{{BUSINESS_NAME}}</div>
            <div class='tag'>{{TAGLINE}}</div>
          </div>
        </a>
        <nav class='nav'>
          <button class='nav-toggle' aria-expanded='false' aria-controls='menu'>Menu</button>
          <ul id='menu' class='nav-list' data-visible='false'>
            <li><a href='about.html'>Practice</a></li>
            <li><a href='specialties.html'>What I Do</a></li>
            <li><a href='approach.html'>How I Work</a></li>
            <li><a href='fees.html'>Investments</a></li>
            <li><a href='faq.html'>FAQs</a></li>
            <li><a href='book.html' class='cta'>{ {PRIMARY_CTA_LABEL} }</a></li>
            <li><a href='contact.html' class='muted'>Connect</a></li>
          </ul>
        </nav>
        <div class='contact-compact'>
          <a href='tel:{{PHONE}}' class='phone' aria-label='call'>{{PHONE}}</a>
        </div>
      </div>
    </header>

    <main>
      <!-- Hero -->
      <section class='hero' id='hero'>
        <div class='wrap hero-grid'>
          <div class='hero-copy'>
            <h1>Short intensives and small-series support for turning tides</h1>
            <p class='lede'>Practical, focused therapy designed as an intensive session or a brief series to help you find clearer next steps without long-term commitment.</p>
            <p class='muted'>Offering confidential telehealth and in-person sessions in {{CITY}}, {{STATE}}. Not a substitute for emergency care.</p>
            <div class='hero-actions'>
              <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>Start an Intensive</a>
              <a class='btn ghost' href='book.html'>See Availability</a>
            </div>
          </div>
          <aside class='hero-panel'>
            <div class='pattern-wrap'>
              <svg class='bg-pattern' viewBox='0 0 600 400' preserveAspectRatio='xMidYMid slice'>
                <defs><pattern id='sitePattern' width='40' height='40' patternUnits='userSpaceOnUse'>
                  <rect width='40' height='40' fill='#0f172a'></rect>
                  <circle cx='20' cy='20' r='6' fill='#6ee7b7' fill-opacity='0.06'></circle>
                </pattern></defs>
                <rect width='100%' height='100%' fill='url(#sitePattern)'></rect>
              </svg>
              <div class='panel-inner'>
                <h3>Intensive Options</h3>
                <ul class='quick-list'>
                  <li><strong>Focus Intensive</strong> — 90-minute deep exploration</li>
                  <li><strong>Short Series</strong> — 3 sessions for immediate shifts</li>
                  <li><strong>Continuity Care</strong> — flexible, periodic check-ins</li>
                </ul>
                <a class='btn small' href='fees.html'>Investment Guide</a>
              </div>
            </div>
          </aside>
        </div>
      </section>

      <!-- Story (why this practice) -->
      <section class='story wrap' id='story'>
        <div class='story-grid'>
          <div class='story-text'>
            <h2>A clinician's practical map for heavy moments</h2>
            <p>I combine evidence-informed tools with clear planning so you walk away with usable steps. Sessions are confidential, scoped to what we agree on, and framed with boundaries and support resources.</p>
            <p class='muted'>I do not provide crisis services. If you are in immediate danger, please call local emergency services or your crisis hotline.</p>
            <a class='btn' href='about.html'>Meet me</a>
          </div>
          <div class='story-quote'>
            <blockquote>
              "We focused on one knot and found a path through—fast, clear, and compassionate." 
              <cite>— a client (shared with permission)</cite>
            </blockquote>
          </div>
        </div>
      </section>

      <!-- Framework (how therapy works) -->
      <section class='framework' id='framework'>
        <div class='wrap'>
          <h2>How I work — an honest framework</h2>
          <ol class='steps'>
            <li><strong>Clarify:</strong> we name the immediate concern and set the session goal.</li>
            <li><strong>Intervene:</strong> targeted strategies and skill practice, attuned to you.</li>
            <li><strong>Plan:</strong> short-term steps and a follow-up rhythm if helpful.</li>
          </ol>
        </div>
      </section>

      <!-- Offers / Proof Gallery -->
      <section class='offers wrap' id='offers'>
        <div class='offers-grid'>
          <div class='offers-list'>
            <h2>Programs & formats</h2>
            <div class='card'>
              <h3>Focus Intensive</h3>
              <p>90-minute focused work to untangle one concern and leave with a concrete plan.</p>
            </div>
            <div class='card'>
              <h3>Short Series</h3>
              <p>3-session short arc for an actionable change with steady momentum.</p>
            </div>
            <div class='card'>
              <h3>Continuity Care</h3>
              <p>Monthly check-ins or flexible blocks when life needs gentle tending.</p>
            </div>
          </div>

          <aside class='proof'>
            <h3>Proof Gallery</h3>
            <div class='testi-rotator' aria-live='polite'>
              <div class='testi' data-index='0'>
                <p class='quote'>&#8220;The intensive helped me make a decision I had been stuck on for years. Clear, practical, and steady support.&#8221;</p>
                <p class='who'>— A client in {{CITY}}</p>
              </div>
              <div class='testi hidden' data-index='1'>
                <p class='quote'>&#8220;Three sessions changed how I handle hard conversations at work. The tools fit my life.&#8221;</p>
                <p class='who'>— Someone who completed the Short Series</p>
              </div>
              <div class='testi hidden' data-index='2'>
                <p class='quote'>&#8220;Monthly check-ins keep me steady without therapy feeling overwhelming. Warm and practical.&#8221;</p>
                <p class='who'>— Ongoing client</p>
              </div>
            </div>

            <div class='badges' role='list'>
              <div class='badge' data-tooltip='Licensed clinician in the state where services are offered'>LICSW</div>
              <div class='badge' data-tooltip='Training in trauma-informed practices'>TRAUMA-INFORMED</div>
              <div class='badge' data-tooltip='Telehealth and in-person practice'>TELEHEALTH</div>
            </div>

            <div class='rotator-controls'>
              <button class='rot-prev' aria-label='previous testimonial'>&larr;</button>
              <button class='rot-next' aria-label='next testimonial'>&rarr;</button>
            </div>
          </aside>
        </div>
      </section>

      <!-- Pricing with comparator -->
      <section class='pricing wrap' id='pricing'>
        <div class='pricing-head'>
          <h2>Investments and options</h2>
          <p class='muted'>Transparent pricing. You can choose single intensives, short series, or a maintenance option.</p>
        </div>

        <div class='pricing-toggle' role='radiogroup' aria-label='pricing toggle'>
          <button class='toggle-btn active' data-mode='package' aria-pressed='true'>Package</button>
          <button class='toggle-btn' data-mode='monthly' aria-pressed='false'>Monthly</button>
        </div>

        <div class='pricing-grid' id='pricingGrid'>
          <div class='price-card'>
            <h3>Focus Intensive</h3>
            <div class='price' data-package='295' data-monthly='110'>$295</div>
            <p class='desc'>One 90-minute session, includes resources and follow-up notes.</p>
            <a class='btn small' href='{{PRIMARY_CTA_URL}}'>Book Intensive</a>
          </div>

          <div class='price-card'>
            <h3>Short Series</h3>
            <div class='price' data-package='760' data-monthly='280'>$760</div>
            <p class='desc'>Three-session series with planning and practice between sessions.</p>
            <a class='btn small' href='{{PRIMARY_CTA_URL}}'>Start Series</a>
          </div>

          <div class='price-card'>
            <h3>Continuity Care</h3>
            <div class='price' data-package='200' data-monthly='200'>$200</div>
            <p class='desc'>Flexible check-ins for ongoing support. Billed per session or by plan.</p>
            <a class='btn small' href='{{PRIMARY_CTA_URL}}'>Arrange Care</a>
          </div>
        </div>
        <p class='muted small'>Insurance is not guaranteed. I will provide superbills upon request. Sessions carried out within agreed scope and confidentiality limits.</p>
      </section>

      <!-- Testimonials block repeated differently order on other pages (note for build) -->
      <section class='testimonials wrap' id='testimonials'>
        <h2>What people say</h2>
        <div class='testi-grid'>
          <figure class='testi-item'>
            <blockquote>"A clear plan after one session helped me sleep better and act with intention."</blockquote>
            <figcaption>— Client</figcaption>
          </figure>
          <figure class='testi-item'>
            <blockquote>"Tools that actually fit my days and relationships."</blockquote>
            <figcaption>— Short Series participant</figcaption>
          </figure>
        </div>
      </section>

      <!-- CTA -->
      <section class='final-cta wrap' id='cta'>
        <div class='cta-panel'>
          <h2>Ready to try a focused approach?</h2>
          <p class='muted'>Choose a one-time intensive or a brief series and we'll make a realistic plan together.</p>
          <div class='cta-actions'>
            <a class='btn primary' href='{{PRIMARY_CTA_URL}}'>Book a Session</a>
            <a class='btn ghost' href='contact.html'>Questions & Confidentiality</a>
          </div>
        </div>
      </section>

    </main>

    <footer class='site-footer'>
      <div class='wrap footer-grid'>
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <p class='muted'>Confidentiality: sessions are confidential except where disclosures are required by law. This practice does not provide emergency services. If you are in crisis, contact local emergency services or your crisis hotline.</p>
        </div>
        <div class='foot-links'>
          <a href='about.html'>About</a>
          <a href='fees.html'>Fees</a>
          <a href='privacy.html'>Privacy</a>
        </div>
        <div class='contact'>
          <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a>
          <a href='tel:{{PHONE}}'>{{PHONE}}</a>
          <div class='location'>{{CITY}}, {{STATE}}</div>
        </div>
      </div>
    </footer>
  </div>

  <script src='assets/js/main.js'></script>
</body>
</html>"} 
