{"path":"assets/css/styles.css","content":"/* Bold playful + mystic modern palette */
:root{--bg:#071029;--card:#0b1220;--accent:#7c3aed;--accent-2:#06b6d4;--muted:#9aa4b2;--surface:#0f1724;--glass:rgba(255,255,255,0.03)}
*{box-sizing:border-box}
body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;background:linear-gradient(180deg, #020617 0%, #071229 100%);color:#e6eef7}
.wrap{max-width:1100px;margin:0 auto;padding:36px}
.topbar{background:linear-gradient(90deg, rgba(124,58,237,0.12), rgba(6,182,212,0.08));backdrop-filter:blur(6px);border-bottom:1px solid rgba(255,255,255,0.03)}
.topbar-grid{display:grid;grid-template-columns:1fr auto auto;align-items:center;gap:16px;padding:18px 24px}
.brand{display:flex;align-items:center;text-decoration:none;color:inherit}
.brand .mark{width:56px;height:56px;margin-right:12px;border-radius:10px;overflow:hidden}
.brand-text .name{font-weight:700;letter-spacing:0.2px}
.brand-text .tag{font-size:13px;color:var(--muted)}
.nav{position:relative}
.nav-toggle{display:none;background:none;border:1px solid rgba(255,255,255,0.04);padding:8px 12px;border-radius:8px;color:inherit}
.nav-list{display:flex;gap:12px;list-style:none;margin:0;padding:0}
.nav-list a{color:inherit;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav-list a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#021022}
.phone{color:var(--muted);text-decoration:none}

.hero{padding:60px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:stretch}
.hero-copy h1{font-size:clamp(24px,4vw,40px);margin:0 0 12px}
.lede{color:#cfe8ff;margin-bottom:12px}
.hero-actions .btn{margin-right:10px}
.hero-panel{background:var(--surface);border-radius:12px;padding:16px}
.pattern-wrap{position:relative;border-radius:10px;overflow:hidden}
.panel-inner{padding:18px}
.quick-list{list-style:none;padding:0;margin:12px 0 16px}
.quick-list li{padding:6px 0}

.story{background:linear-gradient(180deg, rgba(7,18,41,0.55), transparent)}
.story-grid{display:grid;grid-template-columns:1fr 320px;gap:24px;align-items:center}
.story-quote blockquote{font-style:italic;color:#d8f0ea;padding:16px;border-left:3px solid rgba(124,58,237,0.24)}
.muted{color:var(--muted)}
.small{font-size:13px}

.framework{padding:36px 0}
.steps{display:flex;gap:12px;list-style:none;padding:0;margin:12px 0}
.steps li{background:var(--card);padding:16px;border-radius:10px;flex:1}

.offers-grid{display:grid;grid-template-columns:1fr 360px;gap:28px}
.card{background:var(--card);padding:16px;border-radius:10px;margin-bottom:12px}
.proof{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:16px;border-radius:10px}
.testi-rotator{min-height:120px;position:relative}
.testi{transition:opacity 450ms ease,transform 450ms ease}
.testi.hidden{opacity:0;transform:translateY(8px);position:absolute;left:0;right:0}
.badges{display:flex;gap:8px;margin-top:12px}
.badge{background:rgba(255,255,255,0.03);padding:6px 10px;border-radius:8px;font-weight:600;cursor:default;position:relative}
.badge:hover{background:rgba(255,255,255,0.06)}
.rotator-controls{display:flex;gap:8px;margin-top:12px}
.rot-prev,.rot-next{background:none;border:1px solid rgba(255,255,255,0.04);padding:6px 10px;border-radius:8px;color:inherit}

.pricing{padding:36px 0}
.pricing-toggle{display:inline-flex;border-radius:8px;overflow:hidden;border:1px solid rgba(255,255,255,0.04);margin-bottom:18px}
.toggle-btn{background:none;border:0;color:var(--muted);padding:8px 12px;cursor:pointer}
.toggle-btn.active{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#021022}
.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.price-card{background:var(--card);padding:18px;border-radius:10px;text-align:center}
.price{font-size:22px;font-weight:700;margin:6px 0}
.btn{display:inline-block;text-decoration:none;padding:10px 14px;border-radius:10px;background:rgba(255,255,255,0.02);color:inherit;border:1px solid rgba(255,255,255,0.03)}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#021022;border:0}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.04)}
.btn.small{padding:8px 10px;font-size:14px}

.testimonials{padding:36px 0}
.testi-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.testi-item{background:var(--card);padding:16px;border-radius:10px}

.final-cta{padding:40px;text-align:center}
.cta-panel{background:linear-gradient(180deg, rgba(124,58,237,0.06), rgba(6,182,212,0.02));padding:20px;border-radius:12px}
.footer-grid{display:grid;grid-template-columns:1fr auto auto;gap:16px;padding:28px 36px}
.foot-links a{text-decoration:none;color:var(--muted);display:block;margin-bottom:6px}

/* Responsive */
@media(max-width:880px){
  .hero-grid,.story-grid,.offers-grid{grid-template-columns:1fr}
  .nav-toggle{display:inline-block}
  .nav-list{position:absolute;right:12px;top:64px;background:var(--card);padding:12px;border-radius:10px;flex-direction:column;display:none}
  .nav-list[data-visible='true']{display:flex}
  .pricing-grid{grid-template-columns:1fr}
  .steps{flex-direction:column}
}

/* Tooltip */
.tooltip{position:absolute;background:#061125;color:#dff6ff;padding:8px;border-radius:8px;font-size:13px;white-space:nowrap;transform:translateY(-6px);box-shadow:0 6px 18px rgba(2,6,23,0.6);}
"} 
{"path":"assets/js/main.js","content":"(function(){
  'use strict';
  // Mobile nav
  var navToggle = document.querySelector('.nav-toggle');
  var navList = document.getElementById('menu');
  if(navToggle){
    navToggle.addEventListener('click', function(){
      var vis = navList.getAttribute('data-visible') === 'true';
      navList.setAttribute('data-visible', (!vis).toString());
      navToggle.setAttribute('aria-expanded', (!vis).toString());
    });
  }

  // Testimonial rotator
  var testiIndex = 0;
  var testis = Array.prototype.slice.call(document.querySelectorAll('.testi-rotator .testi'));
  var nextBtn = document.querySelector('.rot-next');
  var prevBtn = document.querySelector('.rot-prev');
  function showTesti(i){
    testis.forEach(function(t){ t.classList.add('hidden'); });
    var node = testis[i];
    if(node){ node.classList.remove('hidden'); }
  }
  function advanceTesti(dir){
    testiIndex = (testiIndex + dir + testis.length) % testis.length;
    showTesti(testiIndex);
  }
  if(nextBtn) nextBtn.addEventListener('click', function(){ advanceTesti(1); });
  if(prevBtn) prevBtn.addEventListener('click', function(){ advanceTesti(-1); });
  // auto-rotate every 7s
  setInterval(function(){ advanceTesti(1); }, 7000);

  // Badge tooltips
  var badges = document.querySelectorAll('.badge');
  var tipEl;
  badges.forEach(function(b){
    b.addEventListener('mouseenter', function(e){
      var text = b.getAttribute('data-tooltip');
      tipEl = document.createElement('div');
      tipEl.className = 'tooltip';
      tipEl.textContent = text;
      document.body.appendChild(tipEl);
      var rect = b.getBoundingClientRect();
      tipEl.style.left = (rect.left + rect.width/2 - tipEl.offsetWidth/2) + 'px';
      tipEl.style.top = (rect.top - tipEl.offsetHeight - 8) + 'px';
    });
    b.addEventListener('mouseleave', function(){ if(tipEl){ tipEl.remove(); tipEl=null; } });
  });

  // Pricing comparator with animated numbers
  var toggleBtns = document.querySelectorAll('.toggle-btn');
  var priceEls = document.querySelectorAll('.price-card .price');
  var currentMode = 'package';

  function animateNumber(el, start, end, duration){
    var startTime = null;
    function step(ts){
      if(!startTime) startTime = ts;
      var progress = Math.min((ts - startTime)/duration, 1);
      var value = Math.round(start + (end - start) * easeOutCubic(progress));
      el.textContent = '$' + value;
      if(progress < 1){ requestAnimationFrame(step); }
    }
    requestAnimationFrame(step);
  }
  function easeOutCubic(t){ return 1 - Math.pow(1 - t, 3); }

  function switchPricing(mode){
    priceEls.forEach(function(el){
      var pkg = parseInt(el.getAttribute('data-package'),10) || 0;
      var mon = parseInt(el.getAttribute('data-monthly'),10) || pkg;
      var from = parseInt(el.textContent.replace(/[^0-9]/g,''),10) || (mode=== 'package' ? mon : pkg);
      var to = (mode === 'package') ? pkg : mon;
      animateNumber(el, from, to, 600);
    });
  }

  toggleBtns.forEach(function(btn){
    btn.addEventListener('click', function(){
      toggleBtns.forEach(function(b){ b.classList.remove('active'); b.setAttribute('aria-pressed','false'); });
      btn.classList.add('active');
      btn.setAttribute('aria-pressed','true');
      var mode = btn.getAttribute('data-mode');
      if(mode === currentMode) return;
      currentMode = mode;
      switchPricing(mode);
    });
  });

  // Initialize prices to package
  document.addEventListener('DOMContentLoaded', function(){
    switchPricing('package');
  });

})();"} 
